#!/bin/bash
# List open Entire findings for each open v1-alpha change.
cd /Users/gabe/Projects/callisto || exit 2
while read -r t c b; do
  entire trail finding list --trail "$c" --json 2>/dev/null | python3 -c '
import json,sys
t,c,b=sys.argv[1:4]
try: d=json.load(sys.stdin)
except Exception: print(t,c,b,"ERR"); sys.exit()
items=d if isinstance(d,list) else d.get("findings",[])
if not items: print(t,c,b,"none")
for f in items:
    print(t,c,b,f.get("id"),f.get("severity"),"|",(f.get("body") or f.get("description") or f.get("title") or "")[:500].replace("\n"," "))
' "$t" "$c" "$b"
done < "$1"

